import { definePluginEntry } from "openclaw/plugin-sdk/plugin-entry";
const string = (extra = {}) => ({ type: "string", ...extra });
const integer = (extra = {}) => ({ type: "integer", ...extra });
const object = (properties) => ({ type: "object", additionalProperties: false, properties, required: Object.keys(properties) });
const identity = { channel: string({ enum: ["whatsapp", "instagram"] }), customerId: string({ minLength: 1 }) };
const schemas = {
    buscar_sabor: object({ ...identity, query: string() }), buscar_modelo: object({ ...identity, query: string() }),
    buscar_producto: object({ ...identity, model: string(), flavor: string() }), buscar_por_perfil: object({ ...identity, profile: string() }),
    listar_catalogo: object({}),
    consultar_stock: object({ ...identity, sku: string() }), consultar_precio: object({ ...identity, sku: string() }),
    consultar_entrega: { type: "object", additionalProperties: false, properties: { ...identity, method: string({ enum: ["retiro", "flex", "nacional"] }), locality: string() }, required: ["channel", "customerId", "method"] },
    solicitar_envio_app: object({ ...identity, address: string() }),
    reportar_demora_envio: { type: "object", additionalProperties: false, properties: { ...identity, carrier: string({ enum: ["flex", "correo_argentino", "uber_didi", "otro"] }), promisedEndHour: integer({ minimum: 0, maximum: 23 }), orderReference: string() }, required: ["channel", "customerId", "carrier"] },
    reportar_cambio_envio: { type: "object", additionalProperties: false, properties: { ...identity, product: string(), address: string(), reason: string() }, required: ["channel", "customerId"] },
    reportar_llegada_cambio: { type: "object", additionalProperties: false, properties: { ...identity, status: string(), product: string() }, required: ["channel", "customerId", "status"] },
    coordinar_visita_local: { type: "object", additionalProperties: false, properties: { ...identity, visitType: string({ enum: ["retiro", "cambio"] }), product: string(), preferredTime: string() }, required: ["channel", "customerId", "visitType"] },
    evaluar_producto_fallado: { type: "object", additionalProperties: false, properties: { ...identity, daysSincePurchase: integer({ minimum: 0 }), product: string(), problem: string() }, required: ["channel", "customerId", "daysSincePurchase"] },
    cerrar_conversacion: object(identity),
    consultar_negocio: object({ ...identity, key: string() }), consultar_mayorista: { type: "object", additionalProperties: false, properties: { ...identity, model: string(), quantity: integer({ minimum: 1 }) }, required: ["channel", "customerId", "model"] },
    listar_mayorista: object({}),
    carrito_agregar: object({ ...identity, sku: string(), quantity: integer({ minimum: 1 }) }), carrito_establecer: object({ ...identity, sku: string(), quantity: integer({ minimum: 0 }) }),
    carrito_consultar: object(identity), resumir_pedido: object(identity), solicitar_intervencion_humana: object({ ...identity, reason: string() })
};
const descriptions = {
    buscar_sabor: "Busca el sabor en todas las marcas y solo devuelve productos disponibles.", buscar_modelo: "Lista sabores disponibles de un modelo.", buscar_producto: "Busca un producto específico por modelo y sabor.", buscar_por_perfil: "Recomienda pocos productos disponibles por perfil.", listar_catalogo: "Devuelve la lista completa de modelos, precios y sabores con stock. Si devuelve models, respondé con la lista y nunca solicites intervención.", consultar_stock: "Verifica disponibilidad; no reveles quantity salvo pregunta explícita.", consultar_precio: "Obtiene el precio actual por SKU.", consultar_entrega: "Cotiza retiro o envío Flex y prepara la cotización nacional.", solicitar_envio_app: "OBLIGATORIA cuando el cliente elige Uber o Didi o pregunta su costo. Envía la alerta privada a Telegram, pausa la IA y devuelve el único mensaje permitido.", reportar_demora_envio: "OBLIGATORIA ante un pedido no recibido. Correo indica seguimiento; Flex vencido, Uber/Didi u otro medio envían alerta privada a Telegram y pausan la IA.", reportar_cambio_envio: "Coordina el envío de un cambio ya autorizado. Notifica a Telegram y pausa la IA.", evaluar_producto_fallado: "OBLIGATORIA después de preguntar hace cuántos días compró un producto fallado. Más de 2 días rechaza; 2 o menos notifica a Telegram y pausa la IA.", reportar_llegada_cambio: "OBLIGATORIA si un cliente con un cambio dice que está afuera, viniendo, cerca o por llegar. Notifica a Telegram y pausa la IA.", coordinar_visita_local: "OBLIGATORIA cuando el cliente decide retirar o cambiar un producto en el local. Notifica a Telegram y pausa la IA para acordar el horario.", cerrar_conversacion: "Limpia el estado comercial cuando el cliente confirma que terminó. El siguiente mensaje comienza una conversación nueva.", consultar_negocio: "Obtiene una regla comercial desde NEGOCIO.", consultar_mayorista: "Lista todos los precios mayoristas finales en USD cripto para un modelo específico; si no existe, pausa la IA y notifica al humano.", listar_mayorista: "Devuelve automáticamente todos los modelos y precios mayoristas de Google Sheets. Usala para una consulta mayorista general y nunca solicites intervención.", carrito_agregar: "Guarda internamente un producto elegido; nunca menciones carrito al cliente.", carrito_establecer: "Corrige internamente una cantidad; nunca menciones carrito al cliente.", carrito_consultar: "Lee la selección interna sin mencionar carrito.", resumir_pedido: "Cotiza el pedido sin confirmarlo ni descontar stock.", solicitar_intervencion_humana: "Usala solo ante un caso comercial realmente desconocido; nunca después de listar_catalogo o listar_mayorista exitoso."
};
export default definePluginEntry({ id: "vaprizzio-tools", name: "Vaprizzio Commercial Tools", description: "Herramientas comerciales verificadas", register(api) {
        for (const [name, parameters] of Object.entries(schemas))
            api.registerTool({ name, description: descriptions[name] ?? name, parameters,
                async execute(_id, params) { const configured = api.pluginConfig?.baseUrl; const baseUrl = configured ?? "http://127.0.0.1:3000"; const response = await fetch(`${baseUrl}/api/tools/${name}`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(params) }); const details = await response.json(); if (!response.ok)
                    throw new Error(`VAPRIZZIO_TOOL_ERROR:${response.status}`); return { content: [{ type: "text", text: JSON.stringify(details) }], details }; }
            }, { optional: true });
    } });
